/* From Uiverse.io by gharsh11032000 - Tags: gradient, card, hover, hover effect */
.__UIV_SCOPE__ .card {
  width: 320px;
  height: 350px;
  padding: 20px;
  color: white;
  background: linear-gradient(#212121, #212121) padding-box,
              linear-gradient(145deg, transparent 35%,#e81cff, #40c9ff) border-box;
  border: 2px solid transparent;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transform-origin: right bottom;
  transition: all 0.6s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .card .main-content {
  flex: 1;
}

.__UIV_SCOPE__ .card .header span:first-child {
  font-weight: 600;
  color: #717171;
  margin-right: 4px;
}

.__UIV_SCOPE__ .card .heading {
  font-size: 24px;
  margin: 24px 0 16px;
  font-weight: 600;
}

.__UIV_SCOPE__ .card .categories {
  display: flex;
  gap: 8px;
}

.__UIV_SCOPE__ .card .categories span {
  background-color: #e81cff;
  padding: 4px 8px;
  font-weight: 600;
  text-transform: uppercase;
  font-size: 12px;
  border-radius: 50em;
}

.__UIV_SCOPE__ .card .footer {
  font-weight: 600;
  color: #717171;
  margin-right: 4px;
}

.__UIV_SCOPE__ .card:hover {
  rotate: 8deg;
}
